require_once "../db.php";requireAdmin();$repo=new SpaceRepository($pdo);$id=filter_input(INPUT_GET,"id",FILTER_VALIDATE_INT);if(!$id||$id<1)die("Invalid space ID.");$space=$repo->findById($id);if(!$space)die("Space not found.");$error="";
if($_SERVER["REQUEST_METHOD"]==="POST"){$n=trim($_POST["name"]??"");$c=filter_input(INPUT_POST,"capacity",FILTER_VALIDATE_INT);$p=filter_input(INPUT_POST,"price",FILTER_VALIDATE_FLOAT);$d=trim($_POST["description"]??"");if($n===""||!$c||$c<1||$p===false||$p<0)$error="Enter valid space details.";else{$repo->update($id,$n,$c,$p,$d);header("Location: spaces.php?updated=1");exit;}}
?>
